import{_ as l,l as s,o as e,c as n,v as o,p as i,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"自然循环识别","description":"","frontmatter":{"title":"自然循环识别","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/natural-loops.md","filePath":"cs/natural-loops.md","lastUpdated":1789023840000}'),h={name:"cs/natural-loops.md"};function _(u,a,f,m,E,A){const t=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="自然循环识别" tabindex="-1">自然循环识别 <a class="header-anchor" href="#自然循环识别" aria-label="Permalink to &quot;自然循环识别&quot;">​</a></h1><div class="epigraph"><p>回边的头支配尾。自然循环是头加上不经过头而能到达该回边尾的节点。嵌套由头的包含关系给出。</p><footer>—— 据龙书 9.6；Muchnick；Tarjan 区间分析对照整理</footer></div><p>上一课<a href="/cs/ssa-destruction">SSA 析构</a>提醒优化宜在 SSA 上进行。LICM、IV、展开都要<strong>循环对象</strong>。主干 CFG 课有块与边。缺口是<strong>自然循环</strong>：从回边识别头与体。不可约 CFG 没有整齐的自然循环树，要先变换或放弃部分循环优化。本课钉定义，不写 PGO。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>回边：尾到头，且头支配尾。自然循环：体是所有「不经头能到尾」的节点加头。缺口是<strong>嵌套森林</strong>，不是 φ 放置。</p><p>前置头：造一个唯一外入块，方便 LICM。不可约：两个入口，无单一头，自然循环定义失败。</p><h3 id="自然循环不是「源码的-for」" tabindex="-1">自然循环不是「源码的 for」 <a class="header-anchor" href="#自然循环不是「源码的-for」" aria-label="Permalink to &quot;自然循环不是「源码的 for」&quot;">​</a></h3><p><code>goto</code> 可造不可约。识别结果可能与程序员写的 <code>for</code> 不同（多个 break）。优化认的是 CFG 循环，不是 AST 循环——除非前端保留元数据。</p><p><span class="marginnote">龙书循环。Havlak 不可约循环。LLVM LoopInfo。本课以可约为主。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算支配。找回边。对每条回边扩体（反向 CFG 搜索）。按头支配关系建嵌套。插入 preheader。</p>',11)),(e(),i(c,null,{default:r(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOM%5B%22%E6%94%AF%E9%85%8D%22%5D%20--%3E%20BE%5B%22%E5%9B%9E%E8%BE%B9%22%5D%0A%20%20BE%20--%3E%20BODY%5B%22%E8%87%AA%E7%84%B6%E5%BE%AA%E7%8E%AF%E4%BD%93%22%5D%0A%20%20BODY%20--%3E%20PH%5B%22%E5%89%8D%E7%BD%AE%E5%A4%B4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与多面体：SCoP 检测也要循环树。与向量化：最内自然循环是候选。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>开关与多出口：循环仍自然，只是退出边多，LICM 安全条件更严。不要把 <code>do-while</code> 当没有 preheader 就不能优化——可以造。</p><p>深度：内层先处理是 LICM/IV 的标准序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部不可约变换（节点分裂）。后课默认：可约 CFG 有循环树。下一课 PGO：用轮廓给循环行程与分支概率，驱动展开与内联。</p><p>也不把自然循环当链表上的「环检测」算法课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回边 + 支配 ⇒ 自然循环；嵌套成树。</li><li>preheader 服务外提。</li><li>不可约要另处理。</li><li>出处：Aho et al. 龙书 9.6；Muchnick；对照 Tarjan 区间。</li></ul>',9))])}const P=l(h,[["render",_]]);export{T as __pageData,P as default};
